class TritonOverrides(OpOverrides):
    @staticmethod
    def floor(x):
        return f"tl.math.floor({x})"

    @staticmethod
    def ceil(x):
        return f"tl.math.ceil({x})"

    @staticmethod
    def add(x, y):
        return f"({x} + {y})"

    @staticmethod
    def load(name, index):
        return f"tl.load({name} + ({index}), None)"

class CSE:
    def generate(self, buffer, expr):
        var = self.cache.get(expr)
        if not var:
            var = self.newvar()
            self.cache[expr] = var
            buffer.writeline(f"{var} = {expr}")
        return var
